57	inline static bool CheckNotNull(const aclTensor *self, const aclTensor *mat2, const aclTensor *out)
58	{
59	    OP_CHECK_NULL(self, return false);
60	    OP_CHECK_NULL(mat2, return false);
61	    OP_CHECK_NULL(out, return false);
62	    return true;
