65	static inline bool CheckNpuArchIsSupportBf16(void)
66	{
67	    auto npuArch = op::GetCurrentPlatformInfo().GetCurNpuArch();
68	    return (npuArch == NpuArch::DAV_2201) || (npuArch == NpuArch::DAV_3510);
69	}
70	
71	static inline bool CheckMathType(const aclTensor *self, const aclTensor *mat2, int8_t cubeMathType)
72	{
73	    bool selfFloat = self->GetDataType() == DataType::DT_FLOAT;
74	    bool mat2Float = mat2->GetDataType() == DataType::DT_FLOAT;
75	    auto promoteType = selfFloat || mat2Float ? DataType::DT_FLOAT : self->GetDataType();
76	    return CheckCubeMathTypeForMm(promoteType, cubeMathType);
77	}
78	
79	static bool CheckWeightNzDtype(const aclTensor *self, const aclTensor *mat2)
80	{
81	    if (mat2->GetStorageFormat() == Format::FORMAT_FRACTAL_NZ) {
82	        auto socVersion = GetCurrentPlatformInfo().GetSocVersion();
83	        // weightnz暂不支持self,mat2为bfloat16和float16的数据类型推导
84	        if ((self->GetDataType() == op::DataType::DT_FLOAT16 && mat2->GetDataType() == op::DataType::DT_BF16) ||
85	            (self->GetDataType() == op::DataType::DT_BF16 && mat2->GetDataType() == op::DataType::DT_FLOAT16)) {
86	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
87	                    "The dtypes of self and mat2 must be both DT_BF16 or both DT_FLOAT16, now self's dtype is [%s], "
88	                    "mat2's dtype is [%s]",
89	                    op::ToString(self->GetDataType()).GetString(), op::ToString(mat2->GetDataType()).GetString());
90	            return false;
91	        }
92	        // 当前NZ格式不支持float类型
93	        if (self->GetDataType() == op::DataType::DT_FLOAT || mat2->GetDataType() == op::DataType::DT_FLOAT) {
94	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
95	                    "The dtypes of self and mat2 must be both DT_BF16 or both DT_FLOAT16, now self's dtype is [%s], "
96	                    "mat2's dtype is [%s]",
97	                    op::ToString(self->GetDataType()).GetString(), op::ToString(mat2->GetDataType()).GetString());
98	            return false;
99	        }
100	    }
101	    return true;
102	}
