104	inline static bool CheckWeightNzDtypeValid(const aclTensor *self, const aclTensor *mat2, const aclTensor *out,
105	                                           int8_t cubeMathType)
106	{
107	    bool bf16flag = CheckNpuArchIsSupportBf16();
108	    auto socVersion = GetCurrentPlatformInfo().GetSocVersion();
109	    auto dtypeList = bf16flag ? DTYPE_SUPPORT_LIST : DTYPE_SUPPORT_LIST_WITHOUT_BF16;
110	    OP_CHECK_DTYPE_NOT_SUPPORT(self, dtypeList, return false);
111	    OP_CHECK_DTYPE_NOT_SUPPORT(mat2, dtypeList, return false);
112	    OP_CHECK_DTYPE_NOT_SUPPORT(out, dtypeList, return false);
113	    if (!bf16flag && (self->GetDataType() == op::DataType::DT_BF16 || mat2->GetDataType() == op::DataType::DT_BF16 ||
114	                      out->GetDataType() == op::DataType::DT_BF16)) {
115	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
116	                "Bfloat16 is unsupported by the current SOC version [%s], now self is %s, mat2 is %s, out is %s",
117	                op::ToString(socVersion).GetString(), op::ToString(self->GetDataType()).GetString(),
118	                op::ToString(mat2->GetDataType()).GetString(), op::ToString(out->GetDataType()).GetString());
119	        return false;
120	    }
121	
122	    // keeptype模式支持类型检查
123	    if (cubeMathType == KEEP_DTYPE && !IsInputSupportFp32() &&
124	        (self->GetDataType() == DataType::DT_FLOAT || mat2->GetDataType() == DataType::DT_FLOAT)) {
125	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Self dtype %s or mat2 dtype %s not support under keep type mode.",
126	                op::ToString(self->GetDataType()).GetString(), op::ToString(mat2->GetDataType()).GetString());
127	        return false;
128	    }
129	    if (cubeMathType == KEEP_DTYPE && out->GetDataType() == op::DataType::DT_FLOAT16 &&
130	        self->GetDataType() == op::DataType::DT_FLOAT) {
131	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
132	                "Input tensor's dtype[DT_FLOAT] should be same with output's dtype[DT_FLOAT16].");
133	        return false;
134	    }
135	    return CheckWeightNzDtype(self, mat2);
136	}
