138	// 获取broadcast shape
139	inline static op::Shape GetBroadcastShape(const aclTensor *tensor)
140	{
141	    op::Shape shape;
142	    size_t dimNum = tensor->GetViewShape().GetDimNum();
143	    size_t loopDims = dimNum - 2; // the dims except the last two
144	    for (size_t idx = 0; idx < loopDims; idx++) {
145	        int64_t tmpVal = tensor->GetViewShape().GetDim(idx);
146	        shape.AppendDim(tmpVal);
147	    }
148	    if (shape.GetDimNum() == 0) {
149	        shape.AppendDim(1);
150	    }
151	    return shape;
152	}
153	
154	static bool CheckShapeValid(const aclTensor *self, const aclTensor *mat2)
155	{
156	    op::Shape selfShape = self->GetViewShape();
157	    op::Shape mat2Shape = mat2->GetViewShape();
158	    auto dimTensor1 = selfShape.GetDimNum();
159	    auto dimTensor2 = mat2Shape.GetDimNum();
160	    int64_t selfKDim = 0;
161	    int64_t mat2KDim = 0;
162	
163	    // 超出最大支持维度返回
164	    OP_CHECK_MAX_DIM(self, MAX_SUPPORT_MATMUL_DIMS_NUMS, return false);
165	    OP_CHECK_MAX_DIM(mat2, MAX_SUPPORT_MATMUL_DIMS_NUMS, return false);
166	
167	    // Tensor1 dims number is 0 OR error dims number is 0
168	    if (dimTensor1 == 0 || dimTensor2 == 0) {
169	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Matmul not support %s, %s", op::ToString(selfShape).GetString(),
170	                op::ToString(mat2Shape).GetString());
171	        return false;
172	    } else if (dimTensor2 == 1 || dimTensor2 == 2) { // tensor1 dims number is 1 OR tensor2 dims number is 2
173	        selfKDim = selfShape.GetDim(dimTensor1 - 1); // the rear dim 1
174	        mat2KDim = mat2Shape.GetDim(0);              // the front 0
175	        if (selfKDim != mat2KDim) {
176	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The k-axis of the two inputs are different %s, %s",
177	                    op::ToString(selfShape).GetString(), op::ToString(mat2Shape).GetString());
178	            return false;
179	        }
180	    } else if (dimTensor2 >= 3) {                    // tensor2 dims number >= 3
181	        selfKDim = selfShape.GetDim(dimTensor1 - 1); // the rear dim 1
182	        mat2KDim = mat2Shape.GetDim(dimTensor2 - 2); // the rear dim 2
183	        if (selfKDim != mat2KDim) {
184	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The k-axis of the two inputs are different %s, %s",
185	                    op::ToString(selfShape).GetString(), op::ToString(mat2Shape).GetString());
186	            return false;
187	        }
188	    } else {
189	        ; // 无动作
190	    }
191	    // 检查是否满足broadcast规则
192	    if (dimTensor1 >= 2 && dimTensor2 >= 2) { // the dims larger than 2
193	        op::Shape broadcastShape;
194	        auto selfBroadcastShape = GetBroadcastShape(self);
195	        auto mat2BroadcastShape = GetBroadcastShape(mat2);
196	        if (!BroadcastInferShape(selfBroadcastShape, mat2BroadcastShape, broadcastShape)) {
197	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Broadcast %s and %s failed.",
198	                    op::ToString(self->GetViewShape()).GetString(), op::ToString(mat2->GetViewShape()).GetString());
199	            return false;
200	        }
201	    }
202	
203	    return true;
204	}
