206	static bool CheckFormat(const aclTensor *selfTensor, [[maybe_unused]] const aclTensor *mat2Tensor,
207	                        const aclTensor *outTensor)
208	{
209	    auto selfFormat = selfTensor->GetStorageFormat();
210	    auto outTensorFormat = outTensor->GetStorageFormat();
211	    bool noSupportFormat =
212	        ((selfFormat == Format::FORMAT_FRACTAL_NZ) || (outTensorFormat == Format::FORMAT_FRACTAL_NZ));
213	    if (noSupportFormat) {
214	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, " The 'self' or 'out' tensor currently not supports NZ format");
215	        return false;
216	    }
217	    return true;
218	}
