220	inline static aclnnStatus CheckInputParams(const aclTensor *self, const aclTensor *mat2, const aclTensor *out,
221	                                           int8_t cubeMathType)
222	{
223	    // 1. 检查参数是否为空指针
224	    CHECK_RET(CheckNotNull(self, mat2, out), ACLNN_ERR_PARAM_NULLPTR);
225	
226	    // 2. 检查输入的数据类型是否在API支持的数据类型范围之内，需要根据api定义校验
227	    auto archRule = BuildRule();
228	    CHECK_RET(archRule != nullptr, ACLNN_ERR_PARAM_INVALID);
229	    CHECK_RET(archRule->CheckInput(self, mat2, nullptr, out, cubeMathType), ACLNN_ERR_PARAM_INVALID);
230	
231	    CHECK_RET(CheckWeightNzDtype(self, mat2), ACLNN_ERR_PARAM_INVALID);
232	
233	    // 3. 检查Shape是否支持
234	    CHECK_RET(CheckShapeValid(self, mat2), ACLNN_ERR_PARAM_INVALID);
235	
236	    // 4. 检查self和mat2的format是否符合要求
237	    CHECK_RET(CheckFormat(self, mat2, out), ACLNN_ERR_PARAM_INVALID);
238	
239	    return ACLNN_SUCCESS;
240	}
241	
242	static const aclTensor *ProcessEmptyTensor(const aclTensor *self, const aclTensor *out, aclOpExecutor *executor)
243	{
244	    // 获取shape信息
245	    op::Shape outShape = out->GetViewShape();
246	    auto output = executor->AllocTensor(outShape, self->GetDataType());
247	    CHECK_RET(output != nullptr, nullptr);
248	    if (output->IsEmpty()) {
249	        OP_LOGI("Returning an empty tensor without actually doing calculation.");
250	        return output;
251	    }
252	    FVector<int64_t> fillShape = GetShape(output);
253	    const aclTensor *dims = executor->ConvertToTensor(fillShape.data(), fillShape.size(), op::DataType::DT_INT64);
254	    aclIntArray *shapeArray = executor->AllocIntArray(fillShape.data(), fillShape.size());
255	    const aclScalar *valueScalar = executor->AllocScalar(0);
256	    const aclTensor *valueTensor = executor->ConvertToTensor(valueScalar, out->GetDataType());
257	    auto fillTensor = l0op::Fill(dims, valueTensor, shapeArray, executor);
258	    return fillTensor;
259	}
260	
261	static inline const aclTensor *ContiguousUnsqueezeNd(const aclTensor *input, FVector<int64_t> &dimData,
262	                                                     aclOpExecutor *executor)
263	{
264	    auto inputContiguous = l0op::Contiguous(input, executor);
265	    CHECK_RET(inputContiguous != nullptr, nullptr);
266	
267	    auto dims = executor->AllocIntArray(dimData.data(), dimData.size());
268	    auto output = l0op::UnsqueezeNd(inputContiguous, dims, executor);
269	    CHECK_RET(output != nullptr, nullptr);
270	
271	    return output;
272	}
273	
274	const aclTensor *SetTensorToNZFormat(const aclTensor *input, op::Shape &shape, aclOpExecutor *executor)
275	{
276	    auto formatTensor = executor->CreateView(input, shape, input->GetViewOffset());
277	    CHECK_RET(formatTensor != nullptr, nullptr);
278	    formatTensor->SetStorageFormat(op::Format::FORMAT_FRACTAL_NZ);
279	    formatTensor->SetOriginalFormat(op::Format::FORMAT_ND);
280	    formatTensor->SetViewShape(input->GetViewShape());
281	    return formatTensor;
282	}
283	
284	bool CheckWeightNzShapeValid(const aclTensor *self, const aclTensor *mat2)
285	{
286	    auto socVersion = GetCurrentPlatformInfo().GetSocVersion();
287	    auto npuArch = op::GetCurrentPlatformInfo().GetCurNpuArch();
288	    bool isSupportNpuArch = ((npuArch == NpuArch::DAV_2201) || (npuArch == NpuArch::DAV_3510));
289	    if (!isSupportNpuArch) {
290	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Weight NZ is unsupported by the current SOC version [%s].",
291	                op::ToString(socVersion).GetString());
292	        return false;
293	    }
294	
295	    // mat2 format must be NZ
296	    if (ge::GetPrimaryFormat(mat2->GetStorageFormat()) != Format::FORMAT_FRACTAL_NZ) {
297	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Format of mat2 must be FRACTAL_NZ, actual is %s.",
298	                op::ToString(mat2->GetStorageFormat()).GetString());
299	        return false;
300	    }
301	
302	    // view shape为2
303	    OP_CHECK_WRONG_DIMENSION(self, DIMS_TWO, return false);
304	    OP_CHECK_WRONG_DIMENSION(mat2, DIMS_TWO, return false);
305	
306	    auto storageShape = mat2->GetStorageShape();
307	    auto storageShapeDim = storageShape.GetDimNum();
308	    OP_CHECK(
309	        storageShapeDim == 4,
310	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Only support mat2 storageShapeDim is 4, which are [%zu].", storageShapeDim),
311	        return false);
312	
313	    // check viewShape
314	    op::Shape selfShape = self->GetViewShape();
315	    op::Shape mat2Shape = mat2->GetViewShape();
316	    if (mat2Shape.GetDim(0) == 1 || mat2Shape.GetDim(1) == 1) { // 不支持N=1 or K = 1
317	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Not support mat2 n = 1 or k = 1 when foramt is FRACTAL_NZ, mat2: %s",
318	                op::ToString(mat2Shape).GetString());
319	        return false;
320	    }
321	    auto dimTensor1 = selfShape.GetDimNum();
322	    auto selfKDim = selfShape.GetDim(dimTensor1 - 1);
323	    auto mat2KDim = mat2Shape.GetDim(0);
324	    if (selfKDim != mat2KDim) {
325	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The k-axis of the two inputs are different %s, %s",
326	                op::ToString(selfShape).GetString(), op::ToString(mat2Shape).GetString());
327	        return false;
328	    }
329	    return true;
330	}

