349	op::Shape GetWeightNzShape(const aclTensor *input, bool transpose)
350	{
351	    size_t viewDimNum = input->GetViewShape().GetDimNum();
352	    uint64_t k = transpose ? input->GetViewShape().GetDim(viewDimNum - LAST_FIRST_DIM_INDEX) :
353	                             input->GetViewShape().GetDim(viewDimNum - LAST_SECOND_DIM_INDEX);
354	    uint64_t n = transpose ? input->GetViewShape().GetDim(viewDimNum - LAST_SECOND_DIM_INDEX) :
355	                             input->GetViewShape().GetDim(viewDimNum - LAST_FIRST_DIM_INDEX);
356	    // cal C0
357	    int c0 = NZ_K0_VALUE_16;
358	    if (input->GetDataType() == DataType::DT_FLOAT) {
359	        c0 = NZ_K0_VALUE_32;
360	    }
361	    uint64_t k0 = transpose ? c0 : NZ_STORAGE_PENULTIMATE_DIM;
362	    uint64_t n0 = transpose ? NZ_STORAGE_PENULTIMATE_DIM : c0;
363	    uint64_t k1 = static_cast<uint64_t>(CeilDiv(static_cast<uint64_t>(k), k0));
364	    uint64_t n1 = static_cast<uint64_t>(CeilDiv(static_cast<uint64_t>(n), n0));
365	
366	    op::Shape weightNzShape;
367	    // for batch dims
368	    for (size_t i = 0; i < viewDimNum - LAST_SECOND_DIM_INDEX; i++) {
369	        weightNzShape.AppendDim(input->GetViewShape().GetDim(i));
370	    }
371	
372	    if (transpose) {
373	        weightNzShape.AppendDim(k1);
374	        weightNzShape.AppendDim(n1);
375	    } else {
376	        weightNzShape.AppendDim(n1);
377	        weightNzShape.AppendDim(k1);
378	    }
379	    // 16 c0 外轴固定16, 内轴c0, 不转置时 [n1, k1, 16, c0]， 转置时[k1, n1, 16, c0]
380	    weightNzShape.AppendDim(NZ_STORAGE_PENULTIMATE_DIM);
381	    weightNzShape.AppendDim(c0);
382	
383	    return weightNzShape;
384	}
