386	bool CheckWeightNzStorageShape(const op::Shape &nzShape, const op::Shape &storageShape)
387	{
388	    uint64_t nzDimMultiply = 1;
389	    uint64_t nzDimNum = nzShape.GetDimNum();
390	    for (uint64_t i = 0; i < nzDimNum; i++) {
391	        nzDimMultiply *= nzShape[i];
392	    }
393	
394	    uint64_t storageDimMultiply = 1;
395	    uint64_t storageDimNum = storageShape.GetDimNum();
396	    for (uint64_t i = 0; i < storageDimNum; i++) {
397	        storageDimMultiply *= storageShape[i];
398	    }
399	
400	    return nzDimMultiply == storageDimMultiply;
401	}
