403	static bool GetTransposeAttrValue(const aclTensor *tensor)
404	{
405	    int64_t dim1 = tensor->GetViewShape().GetDimNum() - LAST_FIRST_DIM_INDEX;
406	    int64_t dim2 = tensor->GetViewShape().GetDimNum() - LAST_SECOND_DIM_INDEX;
407	    // check if tensor is contiguous layout
408	    // viewStride [1, K] viewShape [K, N] -> transpose=True
409	    // viewStride [K, 1] viewShape [K, N] -> transpose=False
410	    // K or N = 1 -> transpose=undeterminated
411	    if (tensor->GetViewStrides()[dim2] == 1 && tensor->GetViewStrides()[dim1] == tensor->GetViewShape().GetDim(dim2)) {
412	        OP_LOGI("Matmul GetTransposeAttrValue, find tensor not contiguous.");
413	        return true;
414	    }
415	    return false;
416	}
