418	static const aclTensor *BuildMatMulWeightNzGraph(const aclTensor *self, const aclTensor *mat2, aclTensor *out,
419	                                                 int8_t cubeMathType, aclOpExecutor *executor)
420	{
421	    // 空tensor 处理
422	    if (self->IsEmpty() || mat2->IsEmpty()) {
423	        auto emptyOut = ProcessEmptyTensor(self, out, executor);
424	        CHECK_RET(emptyOut != nullptr, nullptr);
425	        return emptyOut;
426	    }
427	
428	    const aclTensor *matmulOut = nullptr;
429	
430	    // adpat for weightNz transpose scene
431	    bool transposeX2 = GetTransposeAttrValue(mat2);
432	    // swap last two dims value
433	    if (transposeX2) {
434	        const_cast<aclTensor *>(mat2)->SetViewShape(SwapLastTwoDimValue(mat2->GetViewShape()));
435	    }
436	    // Check storage shape Nz shape
437	    op::Shape weightNzShape = GetWeightNzShape(mat2, transposeX2);
438	    if (!CheckWeightNzStorageShape(weightNzShape, mat2->GetStorageShape())) {
439	        OP_LOGE(ACLNN_ERR_PARAM_INVALID,
440	                "mat2'format only support NZ, but now mat2's format is not NZ, please convert the input format to NZ.");
441	        return nullptr;
442	    }
443	
444	    // Set Nz format
445	    mat2 = SetTensorToNZFormat(mat2, weightNzShape, executor);
446	    CHECK_RET(mat2 != nullptr, nullptr);
447	
448	    // 固定selt二维 mat2四维
449	    matmulOut = ExecMmOpWithBias(self, mat2, nullptr, cubeMathType, executor, transposeX2);
450	    CHECK_RET(matmulOut != nullptr, nullptr);
451	
452	    // Reshape to out shape
453	    auto matReshape = l0op::Reshape(matmulOut, out->GetViewShape(), executor);
454	    CHECK_RET(matReshape != nullptr, nullptr);
455	
456	    return matReshape;
457	}
