511	class MatMulDotGraph : public AiInfraMatmul::MatmulGraphImpl {
512	public:
513	    using MatmulGraphImpl::MatmulGraphImpl;
514	
515	    aclnnStatus PreProcess() override
516	    {
517	        auto self = matA;
518	        auto mat2 = matB;
519	
520	        // 检查输入size是否相等
521	        auto dimSize1 = self->GetViewShape().GetDim(0);
522	        auto dimSize2 = mat2->GetViewShape().GetDim(0);
523	        if (dimSize1 != dimSize2) {
524	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Self dimSize [%ld] should be same as mat2 dimSize [%ld].", dimSize1,
525	                    dimSize2);
526	            return ACLNN_ERR_PARAM_INVALID;
527	        }
528	
529	        // 连续性转换
530	        self = l0op::Contiguous(self, executor);
531	        CHECK_RET(self != nullptr, ACLNN_ERR_INNER_NULLPTR);
532	        mat2 = l0op::Contiguous(mat2, executor);
533	        CHECK_RET(mat2 != nullptr, ACLNN_ERR_INNER_NULLPTR);
