151	template <class T>
152	__aicore__ inline void MatrixtoNZ(uint64_t oriN, uint64_t oriD, uint64_t nValue, uint64_t dValue, uint32_t baseN,
153	    uint32_t baseD, uint32_t usedCoreNum, GlobalTensor<T>& tempSrcGlobal, GlobalTensor<T>& tempDstGlobal,
154	    TBuf<TPosition::VECCALC>& tmpBuf)
155	{
156	    if ASCEND_IS_AIV {
157	        uint32_t vBlockIndex = GetBlockIdx();
158	        uint64_t c0Size;
159	        GetSizeC0<T>(c0Size);
160	        LocalTensor<T> tempUb = tmpBuf.Get<T>();
161	        LocalTensor<T> transBuf = tempUb[(TOTAL_UB_SIZE / NUM_TWO) / sizeof(T)];
162	        uint64_t nCnt = MMV3DivCeil(oriN, baseN);
163	        uint64_t dCnt = MMV3DivCeil(dValue, baseD);
164	        uint64_t nBaseTil = nValue - (nCnt - 1) * baseN;   // n方向上的baseN尾块
165	        uint64_t dBaseTail = dValue - (dCnt - 1) * baseD;  // m方向上的baseM尾块
166	        uint64_t totalCnt = nCnt * dCnt;
167	        uint32_t round = (totalCnt + usedCoreNum - 1) / usedCoreNum;  // 每一个core最大做base块计算的次数
168	        uint32_t realRound = 0;                                       // 单核做多少次base块计算
169	        uint32_t preCoreNum = totalCnt % usedCoreNum;  // 从0core开始有多少个core会多做一次base块
170	        uint32_t preTotalBlock = 0;
171	        uint32_t index = 0;  // 当前block_idx的起始基本块Index，按先循环D再循环N的次序
172	        if (preCoreNum == 0) {
173	            preCoreNum = usedCoreNum;
174	        }
175	        // ND
176	        if (vBlockIndex < preCoreNum) {
177	            index = vBlockIndex * round;
178	            // 前面preCoreNum个core会多做一次
179	            realRound = round;
180	        } else {
181	            index = vBlockIndex * (round - 1) + preCoreNum;
182	            // 后面的core会少做一次
183	            realRound = round - 1;
184	        }
185	        uint32_t nCalcLen = 0;
186	        uint32_t dCalcLen = 0;
187	        uint32_t padN = 0;
188	        uint32_t padD = 0;
189	        uint32_t nIndx = 0;
190	        uint32_t dIndx = 0;
191	        uint32_t lastD = oriD % baseD;
192	        for (uint32_t j = 0; j < realRound; ++j) {
193	            if (index < totalCnt) {
194	                if ((index + 1) % (nCnt * dCnt) == 0) {
195	                    // 最后一块是尾块
196	                    nCalcLen = nBaseTil;
197	                    dCalcLen = dBaseTail;
198	                } else if ((index + 1) % (nCnt * dCnt) > (nCnt - 1) * dCnt) {
199	                    // n方向尾块
200	                    nCalcLen = nBaseTil;
201	                    dCalcLen = baseD;
202	                } else if ((index + 1) % dCnt == 0) {
203	                    // d方向尾块
204	                    nCalcLen = baseN;
205	                    dCalcLen = dBaseTail;
206	                } else {
207	                    // 对齐整块
208	                    nCalcLen = baseN;
209	                    dCalcLen = baseD;
210	                }
211	            }
212	            // calc pad_value
213	            nIndx = index / dCnt;
214	            dIndx = index % dCnt;
215	            padN = (nIndx == nCnt - 1) ? nValue - oriN : 0;
216	            padD = (dIndx == dCnt - 1) ? dValue - oriD : 0;  // will be used ???
217	            auto srcGmIdx = (dIndx * baseD + nIndx * baseN * oriD);
218	            auto dstGmIdx = (dIndx * nValue * baseD + nIndx * baseN * c0Size);
219	            CopyPadNd2Nz(tempDstGlobal[dstGmIdx], tempSrcGlobal[srcGmIdx], nCalcLen, dCalcLen, oriN, oriD, tempUb,
220	                transBuf, padN, padD);
221	            event_t eventMTE3MTE2 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE3_MTE2));
222	            SetFlag<HardEvent::MTE3_MTE2>(eventMTE3MTE2);
223	            WaitFlag<HardEvent::MTE3_MTE2>(eventMTE3MTE2);
224	            index += 1;
225	        }
226	    }
227	}
