229	template <class T>
230	__aicore__ inline void MatrixAtoNZV2(GM_ADDR workspace, GM_ADDR src, const TCubeTiling &cfg, bool isTransposeA,
231	    TBuf<TPosition::VECCALC>& tmpBuf, uint32_t baseAN, uint32_t baseAD,
232	    uint32_t batch = 1, uint32_t originalBatch = 1)
233	{
234	    uint64_t c0Size = 16;
235	    GetSizeC0<T>(c0Size);
236	    uint32_t usedCoreNum = cfg.usedCoreNum * GetTaskRation();  // 使用最大的核数
237	    uint64_t alignedMSize = 0;
238	    uint64_t alignedKSize = 0;
239	    alignedMSize = isTransposeA ? MMV3DivCeil(cfg.M, c0Size) * c0Size
240	                                : MMV3DivCeil(cfg.M, ALIGNED_H) * ALIGNED_H;  // N轴转换成分型
241	    alignedKSize = isTransposeA ? MMV3DivCeil(cfg.Ka, ALIGNED_H) * ALIGNED_H
242	                                : MMV3DivCeil(cfg.Ka, c0Size) * c0Size;  // K轴转换成分型
243	    uint64_t oriN = isTransposeA ? cfg.Ka : cfg.M;
244	    uint64_t oriD = isTransposeA ? cfg.M : cfg.Ka;
245	    uint64_t nValue = isTransposeA ? alignedKSize : alignedMSize;
246	    uint64_t dValue = isTransposeA ? alignedMSize : alignedKSize;
247	    GlobalTensor<T> tempSrcGlobal;
248	    GlobalTensor<T> tempDstGlobal;
249	    tempDstGlobal.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(workspace), alignedMSize * alignedKSize);
250	    tempSrcGlobal.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(src), oriD * oriN);
251	#if defined(__DAV_C220_VEC__)
252	    if (batch > 1) {
253	        Nd2nzVnchwBMM(tempDstGlobal, tempSrcGlobal, oriN, oriD, batch, tmpBuf, usedCoreNum);
254	    } else {
255	        // outersize over 8192 and (innersize below 384B when it is even or below 192B when it is odd) for vnchw.
256	        if ((oriN > 8192) && (oriD > 1) && (oriD != c0Size) && (oriD * sizeof(T) <= 192 ||
257	            (oriD * sizeof(T) <= 384 && oriD % 2 == 0) ||
258	            (oriD * sizeof(T) <= 512 && oriD % 4 == 0))) { // 32 is blocksize, 512 is cacheline
259	            Nd2nzVnchwMM(tempDstGlobal, tempSrcGlobal, oriN, oriD, batch, tmpBuf, usedCoreNum);
260	        } else {
261	            // nd2nz cannot exceed the size of UB
262	            if (originalBatch > 1 && nValue * dValue * sizeof(T) * 2 > 192 * 1024) {
263	                Nd2nzVnchwBMM(tempDstGlobal, tempSrcGlobal, oriN, oriD, batch, tmpBuf, usedCoreNum);
264	            } else {
265	                MatrixtoNZ(oriN, oriD, nValue, dValue, baseAN, baseAD, usedCoreNum,
266	                           tempSrcGlobal, tempDstGlobal, tmpBuf);
267	            }
268	        }
269	    }
270	#else
271	    MatrixtoNZ(oriN, oriD, nValue, dValue, baseAN, baseAD, usedCoreNum, tempSrcGlobal, tempDstGlobal, tmpBuf);
272	#endif
273	}
274	
275	template <class T>
276	__aicore__ inline void MatrixBtoNZV2(GM_ADDR workspace, GM_ADDR src, const TCubeTiling &cfg, bool isTransposeB,
277	    TBuf<TPosition::VECCALC> &tmpBuf, uint32_t baseBN, uint32_t baseBD,
278	    uint32_t batch = 1, uint32_t originalBatch = 1)
279	{
280	    uint64_t c0Size = 16;
281	    GetSizeC0<T>(c0Size);
282	    uint32_t usedCoreNum = cfg.usedCoreNum * GetTaskRation();  // 使用最大的核数
283	    uint64_t alignedNSize = 0;
284	    uint64_t alignedKSize = 0;
285	    alignedNSize = isTransposeB ? MMV3DivCeil(cfg.N, ALIGNED_H) * ALIGNED_H : MMV3DivCeil(cfg.N, c0Size) * c0Size;
286	    alignedKSize = isTransposeB ? MMV3DivCeil(cfg.Kb, c0Size) * c0Size : MMV3DivCeil(cfg.Kb, ALIGNED_H) * ALIGNED_H;
287	    uint64_t oriN = isTransposeB ? cfg.N : cfg.Kb;
288	    uint64_t oriD = isTransposeB ? cfg.Kb : cfg.N;
