2019	        } else {
2020	            workspaceSize_ += ops::CeilAlign(args_.nValue, c0Size) * kALignForN * bDtypeSize_;
2021	        }
2022	    }
2023	    OP_LOGI(args_.opName, "final workspace size is %lu", workspaceSize_);
2024	    return ge::GRAPH_SUCCESS;
2025	}
2026	
2027	ge::graphStatus AiInfraMatmulBaseTiling::PostTiling()
2028	{
2029	    size_t tilingDataSize = sizeof(AiInfraMatmulTilingData);
2030	    OP_TILING_CHECK(tilingDataSize % sizeof(uint64_t) != 0,
2031	                    OP_LOGE(args_.opName, "tiling data size[%zu] is not aligned to 8", tilingDataSize),
2032	                    return ge::GRAPH_FAILED);
2033	    OPS_CHECK_NULL_WITH_CONTEXT(context_, context_->GetRawTilingData());
2034	    errno_t ret = memcpy_s(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity(),
2035	                           reinterpret_cast<void *>(&tilingData_), tilingDataSize);
2036	    if (ret != EOK) {
2037	        OP_LOGE(context_->GetNodeName(), "memcpy_s failed, ret=%d", ret);
2038	        return ge::GRAPH_FAILED;
2039	    }
2040	    context_->GetRawTilingData()->SetDataSize(tilingDataSize);
2041	    context_->SetBlockDim(tilingData_.matmulTiling.usedCoreNum);
2042	    // SyncAll和CrossCoreSetFlag<0>属于核间同步，需要设置ScheduleMode为1
2043	    // 含核间同步的场景：
2044	    //   1. MIXND2NZ == V_HEAD_ND2NZ (nd2nz场景，MatmulBaseUnAlignedKernel等含SyncAll)
2045	    //   2. SPLITCOREMODE != BASE
2046	    //   (所有非BASE切K模式：SC_SPLIT_K/NKM/GM_TO_L1/DETERMINISTIC含SyncAll，MULTI_CORE含CrossCoreSetFlag<0>)
2047	    // 不含核间同步的场景（仅CrossCoreSetFlag<0x2>或无同步）：
2048	    //   BASE + MIXND2NZ != V_HEAD_ND2NZ (任意FIXOPTI)
2049	    //   包括MatmulBaseKernel、AL1/BL1FullLoad、UnalignedNKernel(0x2)、CvpBaseKernel(0x2)
2050	    context_->SetScheduleMode(0);
2051	    size_t *workspaces = context_->GetWorkspaceSizes(1); // set workspace
2052	    OP_TILING_CHECK(workspaces == nullptr, CUBE_INNER_ERR_REPORT(context_->GetNodeName(), "workspaces is null"),
2053	                    return ge::GRAPH_FAILED);
2054	    workspaces[0] = workspaceSize_;
2055	
2056	    return ge::GRAPH_SUCCESS;
2057	}
2058	} // namespace ai_infra_matmul
2059	} // namespace optiling

