    OP_CHECK_NULL_WITH_CONTEXT(context_, attrs->GetAttrPointer<bool>(idx));
    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetInputDesc(idx));
    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetInputShape(idx));
    idx++;
    OP_CHECK_NULL_WITH_CONTEXT(context_, attrs->GetAttrPointer<bool>(idx));
    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetInputDesc(idx));
    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetInputShape(idx));
